export const storyPalettes=giftPalettes;
export const storyLayouts={editorial:'Álbum editorial',polaroid:'Foto com dedicatória',imersivo:'Foto em destaque',colagem:'Mural de lembranças',bilhete:'Bilhete de afeto',filme:'Filme de memórias',diptico:'Duas lembranças',capa:'Retrato editorial',postal:'Postal de viagem',galeria:'Galeria particular'};
export function cleanStoryDesign(value={}){const v=value&&typeof value==='object'?value:{};return {nickname:String(v.nickname||'').slice(0,40),title:String(v.title||'').slice(0,100),subtitle:String(v.subtitle||'').slice(0,180),closing:String(v.closing||'').slice(0,160),layout:Object.hasOwn(storyLayouts,v.layout)?v.layout:'editorial',palette:Object.hasOwn(storyPalettes,v.palette)?v.palette:'coral',font:['editorial','clean','classic'].includes(v.font)?v.font:'editorial',duration:Math.max(3,Math.min(15,Number(v.duration)||5)),fit:v.fit==='cover'?'cover':'contain',decoration:['none','capy','letter'].includes(v.decoration)?v.decoration:'capy',showSender:v.showSender!==false,photoPosition:Math.max(0,Math.min(100,(Number.isFinite(Number(v.photoPosition))?Number(v.photoPosition):50))),textAlign:v.textAlign==='left'?'left':'center',transition:['fade','cut','slide','zoom'].includes(v.transition)?v.transition:'fade',background:Object.hasOwn(giftBackgrounds,v.background)?v.background:'cotton',filter:['natural','warm','mono','cinema'].includes(v.filter)?v.filter:'natural',cornerRadius:Math.max(0,Math.min(40,Number.isFinite(Number(v.cornerRadius))?Number(v.cornerRadius):24)),textScale:Math.max(.8,Math.min(1.15,Number(v.textScale)||1)),custom:!!v.custom,soft:cleanAppearance(v).soft,paper:cleanAppearance(v).paper,ink:cleanAppearance(v).ink,accent:cleanAppearance(v).accent};}
