const images=new Map();async function load(src){if(!src)return null;if(!images.has(src))images.set(src,new Promise(resolve=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>resolve(null);image.src=src;}));return images.get(src);}
function round(ctx,x,y,w,h,r=24){ctx.beginPath();ctx.roundRect(x,y,w,h,r);}
function drawImage(ctx,img,x,y,w,h,fit='contain',position=50,radius=10){if(!img)return;ctx.save();round(ctx,x,y,w,h,radius);ctx.clip();const scale=fit==='cover'?Math.max(w/img.width,h/img.height):Math.min(w/img.width,h/img.height),iw=img.width*scale,ih=img.height*scale;ctx.drawImage(img,x+(w-iw)/2,y+(h-ih)*position/100,iw,ih);ctx.restore();}
function storyText(ctx,value,x,y,maxWidth,{size=64,lineHeight=1.16,maxLines=4,font='Georgia',align='center',color='#3a1e14',weight=700,background=null,maxHeight=Infinity,onMetrics=()=>{}}={}){ctx.fillStyle=color;ctx.textAlign=align;ctx.textBaseline='top';ctx.font=`${weight} ${size}px ${font}`;const metrics=drawWrapped(ctx,value,x,y,maxWidth,size*lineHeight,maxLines,{maxHeight:Number.isFinite(maxHeight)?maxHeight:size*lineHeight*maxLines,background,minSize:20});onMetrics(metrics);return metrics.height;}

export function storyDisplayName(data){return cleanStoryDesign(data.storyDesign).nickname||data.recipient||'alguém especial';}
