 const design=cleanStoryDesign(data.storyDesign),appearance=cleanAppearance(data.appearance),palette=appearancePalette(design),photos=data.photos?.length?data.photos:data.photo?[{src:data.photo}]:[],isCover=kind==='cover',photo=isCover?(photos.find(item=>item.id&&item.id===data.selectedPhotoId)||photos.find(item=>item.src===data.photo)||photos[0]):photos[photoIndex]||photos[0],isEnding=kind==='ending',font=design.font==='clean'?'Nunito, Arial, sans-serif':design.font==='classic'?'Georgia, serif':'Fraunces, Georgia, serif';
