 const left=design.textAlign==='left',x=left?88:540,align=left?'left':'center',name=storyDisplayName(data),caption=isCover?design.subtitle||data.message||'As nossas melhores lembranças, em um só lugar.':photo?.caption||'',title=isCover?design.title||'Um mimo para '+name:photo?.title||'',sender=data.experience?.sender;
