  const scale=Math.min(pw/selected.width,ph/selected.height),iw=fit==='cover'?pw:selected.width*scale,ih=fit==='cover'?ph:selected.height*scale,mx=px+(pw-iw)/2,my=py+(ph-ih)*design.photoPosition/100;
