  ctx.save();ctx.filter={natural:'none',warm:'sepia(.12) saturate(1.04)',mono:'grayscale(1)',cinema:'contrast(1.08) saturate(.82)'}[design.filter];drawImage(ctx,selected,fullBleed?px:mx,fullBleed?py:my,fullBleed?pw:iw,fullBleed?ph:ih,fit,design.photoPosition,appearance.photoFrame==='round'?Math.max(32,design.cornerRadius):design.cornerRadius);ctx.restore();
