export function initStoryDesignEditor({getState,onChange}){
 const panel=document.createElement('section');panel.className='story-design-editor';panel.innerHTML='<h3>O jeito da sua história</h3><p>Escolha uma composição. A prévia ao lado usa suas próprias fotos e palavras.</p><div class="field"><label for="story-nickname">Como você chama essa pessoa?</label><input id="story-nickname" maxlength="40" placeholder="Apelido: meu bem, vó Lúcia, Juju…"><small>O nome oficial continua no campo do presente.</small></div><div class="field"><label for="story-title">Título de abertura</label><input id="story-title" maxlength="100" placeholder="Ex.: Juju, isso é muito a nossa cara."></div><div class="field"><label for="story-subtitle">Dedicatória na capa</label><textarea id="story-subtitle" maxlength="180" rows="3" placeholder="Uma frase que só vocês entendem."></textarea></div><div class="story-layouts" role="group" aria-label="Composição do Story"></div><div class="story-palette-options" role="group" aria-label="Paleta do Story"></div><div class="story-design-fields"><div class="field"><label for="story-font">Tipografia</label><select id="story-font"><option value="editorial">Editorial · com serifa</option><option value="clean">Contemporânea · sem serifa</option><option value="classic">Clássica · Georgia</option></select></div><div class="field"><label for="story-alignment">Alinhamento</label><select id="story-alignment"><option value="center">Centralizado</option><option value="left">À esquerda</option></select></div><div class="field"><label for="story-fit">Enquadramento padrão</label><select id="story-fit"><option value="contain">Foto inteira, sem corte</option><option value="cover">Preencher a moldura</option></select></div><div class="field"><label for="story-duration">Tempo por foto</label><select id="story-duration"><option value="3">3 segundos</option><option value="5">5 segundos</option><option value="8">8 segundos</option><option value="10">10 segundos</option><option value="15">15 segundos</option></select></div><div class="field"><label for="story-decoration">Detalhe ilustrado</label><select id="story-decoration"><option value="capy">Capivara</option><option value="letter">Cartinha</option><option value="none">Só fotos e palavras</option></select></div><div class="field"><label for="story-transition">Troca entre fotos</label><select id="story-transition"><option value="fade">Suave</option><option value="cut">Direta</option><option value="slide">Deslizar</option><option value="zoom">Aproximar</option></select></div></div><div class="field"><label for="story-position">Posição da foto ao preencher</label><input type="range" id="story-position" min="0" max="100" value="50"><small>Ajuste para preservar o rosto. Em “foto inteira”, não há corte.</small></div><div class="field"><label for="story-closing">Mensagem de encerramento</label><textarea id="story-closing" maxlength="160" rows="3" placeholder="Ex.: Que venham os próximos capítulos, meu bem."></textarea></div><label class="story-show-sender"><input type="checkbox" id="story-show-sender" checked> Mostrar de quem é o presente</label>';
 document.querySelector('.format-field').after(panel);document.querySelector('.experience-identity').append(panel.querySelector('#story-nickname').closest('.field'));const patch=value=>{const storyDesign=cleanStoryDesign({...getState().storyDesign,...value}),appearance=cleanAppearance({...getState().appearance,...Object.fromEntries(['custom','paper','ink','accent','soft','palette','background'].map(key=>[key,storyDesign[key]])),fontFamily:storyDesign.font});onChange({storyDesign,appearance,...(value.decoration==='capy'&&getState().character==='none'?{character:'capy'}:{})});};
 const extra=document.createElement('details');extra.className='story-extra-design';extra.innerHTML='<summary>Mais personalização</summary><div class="field"><label for="story-background">Fundo do Story</label><select id="story-background"></select></div><div class="field"><label for="story-filter">Tratamento das fotos</label><select id="story-filter"><option value="natural">Cores naturais</option><option value="warm">Lembrança quente</option><option value="mono">Preto e branco</option><option value="cinema">Clima de cinema</option></select></div><div class="field"><label for="story-radius">Cantos da fotografia</label><input type="range" id="story-radius" min="0" max="40"></div><div class="field"><label for="story-scale">Tamanho do texto</label><input type="range" id="story-scale" min="80" max="115"></div><label><input type="checkbox" id="story-custom-colors"> Criar minha própria paleta</label><div class="appearance-color-inputs"><label>Papel<input type="color" id="story-paper"></label><label>Texto<input type="color" id="story-ink"></label><label>Destaque<input type="color" id="story-accent"></label></div><p>O contraste é ajustado para manter a leitura. A foto original é preservada.</p>';panel.append(extra);for(const [key,label] of Object.entries(giftBackgrounds))extra.querySelector('#story-background').add(new Option(label,key));extra.querySelector('#story-scale').addEventListener('input',event=>patch({textScale:Number(event.target.value)/100}));extra.querySelector('#story-custom-colors').addEventListener('change',event=>patch({custom:event.target.checked}));for(const [id,key] of [['story-paper','paper'],['story-ink','ink'],['story-accent','accent']])extra.querySelector('#'+id).addEventListener('input',event=>patch({[key]:event.target.value,custom:true}));
 const bindings={'story-nickname':'nickname','story-title':'title','story-subtitle':'subtitle','story-closing':'closing','story-font':'font','story-alignment':'textAlign','story-fit':'fit','story-duration':'duration','story-decoration':'decoration','story-position':'photoPosition','story-transition':'transition','story-background':'background','story-filter':'filter','story-radius':'cornerRadius'};
 for(const [id,key] of Object.entries(bindings))document.getElementById(id).addEventListener('input',event=>patch({[key]:event.target.value}));panel.querySelector('#story-show-sender').addEventListener('change',event=>patch({showSender:event.target.checked}));
 for(const [key,label] of Object.entries(storyLayouts)){const button=document.createElement('button');button.type='button';button.dataset.storyLayout=key;button.textContent=label;button.className='story-layout-option '+key;button.addEventListener('click',()=>patch({layout:key}));panel.querySelector('.story-layouts').append(button);}
 for(const [key,palette] of Object.entries(storyPalettes)){const button=document.createElement('button');button.type='button';button.dataset.storyPalette=key;button.textContent=palette.label;button.style.setProperty('--story-accent',palette.accent);button.style.setProperty('--story-paper',palette.paper);button.addEventListener('click',()=>patch({palette:key,custom:false}));panel.querySelector('.story-palette-options').append(button);}
 function render(){panel.hidden=getState().format!=='stories';document.getElementById('story-nickname').closest('.field').hidden=panel.hidden;const value=cleanStoryDesign(getState().storyDesign);for(const [id,key] of Object.entries(bindings)){const input=document.getElementById(id);if(input.value!==String(value[key]))input.value=value[key];}panel.querySelector('#story-show-sender').checked=value.showSender;extra.querySelector('#story-scale').value=value.textScale*100;extra.querySelector('#story-custom-colors').checked=value.custom;for(const key of ['paper','ink','accent'])extra.querySelector('#story-'+key).value=value[key];panel.querySelectorAll('[data-story-layout]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.storyLayout===value.layout)));panel.querySelectorAll('[data-story-palette]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.storyPalette===value.palette)));}render();return {render,panel};
}
